135	    if (!snapshotRes) {
136	      return { snapshotNeeded: false, latestCount: currentCount };
137	    }
138	    const { id: lastSavedMessageId, stateRoot: lastSavedStateRoot } = snapshotRes;
139	    const messageIndex = extractMessageIndex(lastSavedMessageId);
140	    lastSavedSnapshot = lastSavedStateRoot;
141	    lastSavedCount = messageIndex;
142	    const lastClaimData = await fetchLastClaimedEpoch(veaOutbox.target, chainId);
143	    lastClaimedStateroot = lastClaimData ? lastClaimData.stateRoot : null;
144	  }
145	  const epochNow = Math.floor(Date.now() / (1000 * epochPeriod));
146	  const currentSnapshot = await veaInbox.snapshots(epochNow);
147	  const currentStateRoot = await veaOutbox.stateRoot();
148	  if (currentCount > lastSavedCount) {
149	    return { snapshotNeeded: true, latestCount: currentCount };
150	  } else if (
151	    currentSnapshot == ZeroHash &&
152	    lastSavedSnapshot != currentStateRoot &&
153	    lastSavedSnapshot != lastClaimedStateroot
154	  ) {
155	    return { snapshotNeeded: true, latestCount: currentCount };
156	  }
157	  return { snapshotNeeded: false, latestCount: currentCount };
158	};
