160	function extractMessageIndex(id: string): number {
161	  if (id === undefined) return 0;
162	  const parts = id.split("-");
163	  if (parts.length < 2) {
164	    throw new Error(`Invalid message-id format: ${id}`);
165	  }
166	  // everything after the first dash is the index
167	  const idxStr = parts.slice(1).join("-");
168	  const idx = parseInt(idxStr, 10);
169	  if (Number.isNaN(idx)) {
170	    throw new Error(`Cannot parse index from "${idxStr}"`);
171	  }
172	  return idx;
173	}
